/// Save-as into a path *outside* the workspace boundary is still rejected, even when the missing
/// dirs are within the workspace. The boundary check must run before any directory creation —
/// otherwise a save-as into `../escape/x.txt` could silently create dirs above the workspace root.
#[tokio::test]
async fn save_as_does_not_create_dirs_outside_workspace() {
    let outer = tempfile::tempdir().unwrap();
    let workspace = outer.path().join("proj");
    std::fs::create_dir_all(&workspace).unwrap();
    let workspace_canonical = std::fs::canonicalize(&workspace).unwrap();

    let server = spawn_for_test("test-proj", vec![workspace_canonical.clone()])
        .await
        .unwrap();
    let mut ws = Ws::connect(&server).await;
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: false,
        },
    )
    .await;
    let scratch: BufferOpenResult = send_request::<BufferOpen>(
        &mut ws,
        &BufferOpenParams {
            transient: None,
            buffer_id: None,
            path_index: None,
            relative_path: None,
            language: None,
            create_if_missing: false,
            jump_to: None,
            ..Default::default()
        },
    )
    .await;
    let err = send_request_expect_err::<BufferSave>(
        &mut ws,
        &BufferSaveParams {
            buffer_id: scratch.buffer_id,
            path_index: Some(0),
            relative_path: Some("../escape/x.txt".into()),
            overwrite: false,
        },
    )
    .await;
    assert!(
        err.contains("outside the workspace"),
        "unexpected error: {err}"
    );
    assert!(
        !workspace_canonical
            .parent()
            .unwrap()
            .join("escape")
            .exists(),
        "must not have created an `escape` dir alongside the workspace"
    );
    drop(server);
}

/// Save-as into a path already owned by another open buffer is rejected — otherwise we'd
/// silently displace the other buffer.
#[tokio::test]
async fn save_as_rejects_path_conflict_with_open_buffer() {
    let dir = tempfile::tempdir().unwrap();
    let dir_path = dir.path().to_path_buf();
    std::fs::write(dir_path.join("existing.txt"), "old content\n").unwrap();
    let server = spawn_for_test("test-proj", vec![dir_path]).await.unwrap();
    let mut ws = Ws::connect(&server).await;
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: false,
        },
    )
    .await;

    // Open the existing file (now claimed by buffer A).
    let _: BufferOpenResult = send_request::<BufferOpen>(
        &mut ws,
        &BufferOpenParams {
            transient: None,
            buffer_id: None,
            path_index: Some(0),
            relative_path: Some("existing.txt".into()),
            language: None,
            create_if_missing: false,
            jump_to: None,
            ..Default::default()
        },
    )
    .await;
    // Open a fresh scratch (buffer B).
    let scratch: BufferOpenResult = send_request::<BufferOpen>(
        &mut ws,
        &BufferOpenParams {
            transient: None,
            buffer_id: None,
            path_index: None,
            relative_path: None,
            language: None,
            create_if_missing: false,
            jump_to: None,
            ..Default::default()
        },
    )
    .await;

    // Try to save-as scratch -> existing.txt. Expect error, expect the on-disk content
    // untouched.
    let msg = send_request_expect_err::<BufferSave>(
        &mut ws,
        &BufferSaveParams {
            buffer_id: scratch.buffer_id,
            path_index: Some(0),
            relative_path: Some("existing.txt".into()),
            overwrite: false,
        },
    )
    .await;
    assert!(
        msg.contains("already open"),
        "expected conflict message, got: {msg}"
    );

    drop(server);
}

