// ---- file watcher ------------------------------------------------------------------------------

/// Spin up the server with one buffer subscribed to a viewport — the minimum setup for the
/// watcher to fire `buffer/state` pushes on file-change events. Returns the canonical disk
/// path so the test can write to it externally.
async fn setup_watched_buffer(
    initial: &str,
) -> (
    aether_server::ServerHandle,
    Ws,
    u64,                // buffer_id
    std::path::PathBuf, // file path
) {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("watched.txt");
    std::fs::write(&path, initial).unwrap();
    // Backdate the file so every subsequent external write is strictly newer than the mtime the
    // buffer records on load — otherwise a fast back-to-back write can land on an identical mtime,
    // which the watcher's self-save filter would mistake for our own write.
    stamp_modified_behind(&path);
    let dir_path = dir.path().to_path_buf();

    let mut server = spawn_for_test("test-proj", vec![dir_path]).await.unwrap();
    server.keep_alive(dir);
    let mut ws = Ws::connect(&server).await;
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: false,
        },
    )
    .await;
    let open: BufferOpenResult = send_request::<BufferOpen>(
        &mut ws,
        &BufferOpenParams {
            transient: None,
            buffer_id: None,
            path_index: Some(0),
            relative_path: Some("watched.txt".into()),
            language: None,
            create_if_missing: false,
            jump_to: None,
            ..Default::default()
        },
    )
    .await;
    let _sub: ViewportSubscribeResult = send_request::<ViewportSubscribe>(
        &mut ws,
        &ViewportSubscribeParams {
            buffer_id: aether_protocol::ViewId(open.buffer_id),
            cols: 80,
            rows: 10,
            overscan_rows: 0,
            scroll: ScrollPosition {
                element: 0,
                line: 0,
                sub_row: 0.0,
            },
            focus: None,
            wrap: WrapMode::Soft,
            continuation_marker_width: 0,
            tab_width: 4,
            diff_view: false,
        },
    )
    .await;
    (server, ws, open.buffer_id, path)
}

#[tokio::test]
async fn watcher_reloads_clean_buffer_on_external_write() {
    let (server, mut ws, buffer_id, path) = setup_watched_buffer("hello\n").await;

    // External edit. Buffer was clean, so the server should silently reload + push state.
    std::fs::write(&path, "hello world\n").unwrap();

    let state_push =
        expect_notification_within::<BufferState>(&mut ws, std::time::Duration::from_secs(5)).await;
    assert_eq!(state_push.buffer_id, buffer_id);
    assert!(
        !state_push.externally_modified,
        "clean buffer should silently reload, not flag"
    );
    assert!(!state_push.externally_deleted);

    drop(server);
}

/// Regression: a silent reload that shrinks the file below the viewport's scroll position must
/// clamp the stored scroll and push a non-empty, in-range window. Previously the stale scroll
/// made `pushed_range` collapse to an empty range past EOF and the client showed a blank buffer.
#[tokio::test]
async fn watcher_reload_of_shrunken_file_keeps_viewport_in_range() {
    let long: String = (0..200).map(|i| format!("line {i}\n")).collect();
    let (server, mut ws, buffer_id, path) = setup_watched_buffer(&long).await;

    // Re-subscribe deep into the file (supersedes the setup's line-0 viewport).
    let sub: ViewportSubscribeResult = send_request::<ViewportSubscribe>(
        &mut ws,
        &ViewportSubscribeParams {
            buffer_id: aether_protocol::ViewId(buffer_id),
            cols: 80,
            rows: 10,
            overscan_rows: 5,
            scroll: ScrollPosition {
                element: 0,
                line: 150,
                sub_row: 0.0,
            },
            focus: None,
            wrap: WrapMode::Soft,
            continuation_marker_width: 0,
            tab_width: 4,
            diff_view: false,
        },
    )
    .await;
    assert_eq!(
        loaded_lines(&sub.window).0,
        145,
        "the subscribe loads from the overscan above line 150"
    );

    // Park the cursor deep too, so the reload's clamp has something to do.
    let st: CursorState = send_request::<CursorMove>(
        &mut ws,
        &CursorMoveParams {
            buffer_id,
            motion: Motion::Goto {
                position: LogicalPosition { line: 150, col: 0 },
            },
            extend_selection: false,
        },
    )
    .await;
    assert_eq!(st.position.line, 150);

    // External rewrite far shorter than the scroll position — the watcher silently reloads.
    std::fs::write(&path, "a\nb\nc\nd\ne\n").unwrap();

    // 6 lines: ropey counts the trailing empty line after the final newline.
    let new_line_count = 6;
    let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(5);
    let push = loop {
        let remaining = deadline.saturating_duration_since(tokio::time::Instant::now());
        let p = expect_notification_within::<ViewportLinesChanged>(&mut ws, remaining).await;
        // One row per line: the rewritten lines are short.
        if total_rows(&p.window) == new_line_count {
            break p;
        }
    };

    // The loaded slice had fallen off the end of the shrunken file, so it clamps to the file's
    // tail — with rows 10 + overscan 5 that is the whole file. The essential invariants:
    // non-empty and inside the new bounds.
    let (start, end) = loaded_lines(&push.window);
    assert!(
        start < end,
        "pushed window must be non-empty, got {start:?}..{end:?}"
    );
    assert!(end <= new_line_count);
    assert_eq!((start, end), (0, new_line_count));
    assert_eq!(push.window.root.lines().len(), (end - start) as usize);

    // The clamped cursor rides the push — without it the client shows a stale position (and no
    // cursor block at all) until the next round-trip.
    let cursor = push
        .cursor
        .expect("reload's lines_changed carries the authoritative cursor");
    assert_eq!(
        cursor.position.line,
        new_line_count - 1,
        "cursor clamped into the new bounds"
    );

    // The healed scroll state also serves follow-up scrolls normally.
    let scrolled = window_from_row(&mut ws, sub.viewport_id, 0, 15).await;
    assert_eq!(loaded_lines(&scrolled.window).0, 0);
    assert!(!scrolled.window.root.lines().is_empty());

    drop(server);
}

/// Subscribing with a stale out-of-range scroll (e.g. a restored position for a file that shrank
/// while unwatched) must anchor to the end of the buffer, not return an empty window.
#[tokio::test]
async fn subscribe_with_scroll_past_eof_returns_non_empty_window() {
    let (server, mut ws, buffer_id) = setup_with_buffer("a\nb\nc\n").await;

    let sub: ViewportSubscribeResult = send_request::<ViewportSubscribe>(
        &mut ws,
        &ViewportSubscribeParams {
            buffer_id: aether_protocol::ViewId(buffer_id),
            cols: 80,
            rows: 10,
            overscan_rows: 0,
            scroll: ScrollPosition {
                element: 0,
                line: 1000,
                sub_row: 0.0,
            },
            focus: None,
            wrap: WrapMode::Soft,
            continuation_marker_width: 0,
            tab_width: 4,
            diff_view: false,
        },
    )
    .await;

    let w = &sub.window;
    assert_eq!(total_rows(w), 4);
    let (first, last) = loaded_lines(w);
    assert!(
        first < last,
        "window must be non-empty, got {first}..{last}"
    );
    assert!(last <= 4);
    assert!(!w.root.lines().is_empty());

    drop(server);
}

#[tokio::test]
async fn watcher_flags_dirty_buffer_on_external_write() {
    let (server, mut ws, buffer_id, path) = setup_watched_buffer("hello\n").await;

    // Dirty the buffer: insert at start.
    let _edit: EditResult = send_request::<InputText>(
        &mut ws,
        &InputTextParams {
            buffer_id,
            text: "x".into(),
            select_pasted: false,
            replace_selection: false,
            at: None,
        },
    )
    .await;
    // Drain the edit's lines_changed push so the next expect_notification gets the watcher's.
    let _ = expect_notification::<ViewportLinesChanged>(&mut ws).await;

    // External write while dirty: server should flag externally_modified, not silently reload.
    std::fs::write(&path, "external content\n").unwrap();

    let state_push =
        expect_notification_within::<BufferState>(&mut ws, std::time::Duration::from_secs(5)).await;
    assert_eq!(state_push.buffer_id, buffer_id);
    assert!(
        state_push.externally_modified,
        "expected externally_modified=true"
    );
    assert!(!state_push.externally_deleted);

    // Save without overwrite should be rejected.
    let err = send_request_expect_err::<BufferSave>(
        &mut ws,
        &BufferSaveParams {
            buffer_id,
            path_index: None,
            relative_path: None,
            overwrite: false,
        },
    )
    .await;
    assert!(
        err.to_lowercase().contains("modified") || err.to_lowercase().contains("disk"),
        "expected external-mod error, got: {err}"
    );

    // Retry with overwrite: succeeds. We may still receive the `buffer/state` push from
    // earlier or other intermediate frames; `send_request` drains them and returns on the
    // matching response.
    let save: BufferSaveResult = send_request::<BufferSave>(
        &mut ws,
        &BufferSaveParams {
            buffer_id,
            path_index: None,
            relative_path: None,
            overwrite: true,
        },
    )
    .await;
    assert!(save.saved_at_unix_ms > 0);
    assert_eq!(std::fs::read_to_string(&path).unwrap(), "xhello\n");

    drop(server);
}

#[tokio::test]
async fn watcher_flags_deleted_file() {
    let (server, mut ws, buffer_id, path) = setup_watched_buffer("hello\n").await;

    std::fs::remove_file(&path).unwrap();

    // First state push: externally_deleted = true. The watcher may also fire other events
    // depending on the OS (e.g. modify on the parent dir); loop until we see the deleted flag.
    let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(5);
    let mut seen_deleted = false;
    while tokio::time::Instant::now() < deadline {
        let p = match tokio::time::timeout(
            std::time::Duration::from_millis(500),
            expect_notification::<BufferState>(&mut ws),
        )
        .await
        {
            Ok(p) => p,
            Err(_) => continue,
        };
        if p.externally_deleted && p.buffer_id == buffer_id {
            seen_deleted = true;
            break;
        }
    }
    assert!(seen_deleted, "no buffer/state with externally_deleted=true");

    // Save (with overwrite) recreates the file.
    let _save: BufferSaveResult = send_request::<BufferSave>(
        &mut ws,
        &BufferSaveParams {
            buffer_id,
            path_index: None,
            relative_path: None,
            overwrite: true,
        },
    )
    .await;
    assert!(path.exists(), "save should recreate the deleted file");
    assert_eq!(std::fs::read_to_string(&path).unwrap(), "hello\n");

    drop(server);
}

#[tokio::test]
async fn watcher_covers_open_buffer_inside_gitignored_dir() {
    // Workspace-root watch registration is gitignore-aware (it skips e.g. `target/`), but a
    // buffer the user opens *inside* an ignored tree still gets external-change events via the
    // targeted parent-dir watch `buffer/open` adds. Regression guard for the per-directory
    // watcher scheme — under the old recursive watch this coverage was implicit.
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    std::fs::create_dir_all(root.join(".git")).unwrap(); // marks the repo so .gitignore applies
    std::fs::write(root.join(".gitignore"), "generated/\n").unwrap();
    std::fs::create_dir_all(root.join("generated")).unwrap();
    let path = root.join("generated/out.txt");
    std::fs::write(&path, "v1\n").unwrap();
    // Strictly-greater mtime for the external write (see `setup_watched_buffer`).
    stamp_modified_behind(&path);
    let root_path = root.to_path_buf();

    let server = spawn_for_test("test-proj", vec![root_path]).await.unwrap();
    let mut ws = Ws::connect(&server).await;
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: false,
        },
    )
    .await;
    let open: BufferOpenResult = send_request::<BufferOpen>(
        &mut ws,
        &BufferOpenParams {
            path_index: Some(0),
            relative_path: Some("generated/out.txt".into()),
            ..Default::default()
        },
    )
    .await;
    let _sub: ViewportSubscribeResult = send_request::<ViewportSubscribe>(
        &mut ws,
        &ViewportSubscribeParams {
            buffer_id: aether_protocol::ViewId(open.buffer_id),
            cols: 80,
            rows: 10,
            overscan_rows: 0,
            scroll: ScrollPosition {
                element: 0,
                line: 0,
                sub_row: 0.0,
            },
            focus: None,
            wrap: WrapMode::Soft,
            continuation_marker_width: 0,
            tab_width: 4,
            diff_view: false,
        },
    )
    .await;

    // External edit. Clean buffer → silent reload + buffer/state push, same as an un-ignored file.
    std::fs::write(&path, "v2\n").unwrap();
    let state_push =
        expect_notification_within::<BufferState>(&mut ws, std::time::Duration::from_secs(5)).await;
    assert_eq!(state_push.buffer_id, open.buffer_id);
    assert!(
        !state_push.externally_modified,
        "clean buffer should reload silently, not be flagged"
    );

    drop(server);
}

/// Connect a client, activate the named workspace, open `watched.txt` under root 0, and subscribe
/// a viewport (so the watcher's `buffer/state` pushes reach it). Returns the socket + buffer id.
async fn connect_and_open_watched(ws_url: &str, workspace: &str) -> (Ws, u64) {
    let mut ws = Ws::connect_url(ws_url).await;
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: workspace.into(),
            open_last: false,
        },
    )
    .await;
    let open: BufferOpenResult = send_request::<BufferOpen>(
        &mut ws,
        &BufferOpenParams {
            transient: None,
            buffer_id: None,
            path_index: Some(0),
            relative_path: Some("watched.txt".into()),
            language: None,
            create_if_missing: false,
            jump_to: None,
            ..Default::default()
        },
    )
    .await;
    let _sub: ViewportSubscribeResult = send_request::<ViewportSubscribe>(
        &mut ws,
        &ViewportSubscribeParams {
            buffer_id: aether_protocol::ViewId(open.buffer_id),
            cols: 80,
            rows: 10,
            overscan_rows: 0,
            scroll: ScrollPosition {
                element: 0,
                line: 0,
                sub_row: 0.0,
            },
            focus: None,
            wrap: WrapMode::Soft,
            continuation_marker_width: 0,
            tab_width: 4,
            diff_view: false,
        },
    )
    .await;
    (ws, open.buffer_id)
}

/// Two workspaces sharing one root, one client on each, the same file open in both — two buffers
/// over one shared document. Disk events land on the document once, and the fixup fan-out must
/// reach both workspaces' viewers, not just the buffer the watcher found first.
async fn setup_overlapping_workspaces_watched_buffer(
    initial: &str,
) -> (
    aether_server::ServerHandle,
    Ws,
    u64, // buffer id in proj-a
    Ws,
    u64, // buffer id in proj-b
    std::path::PathBuf,
) {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("watched.txt");
    std::fs::write(&path, initial).unwrap();
    // As in `setup_watched_buffer`: keep later writes' mtimes strictly above the loaded one so
    // the self-save filter can't mistake them for our own.
    stamp_modified_behind(&path);
    let dir_path = dir.path().to_path_buf();

    let mut server = spawn_for_test_multi(vec![
        ("proj-a".into(), vec![dir_path.clone()]),
        ("proj-b".into(), vec![dir_path]),
    ])
    .await
    .unwrap();
    server.keep_alive(dir);
    let (ws_a, buf_a) = connect_and_open_watched(&server.ws_url(), "proj-a").await;
    let (ws_b, buf_b) = connect_and_open_watched(&server.ws_url(), "proj-b").await;
    (server, ws_a, buf_a, ws_b, buf_b, path)
}

#[tokio::test]
async fn watcher_fans_out_external_write_to_buffers_in_all_workspaces() {
    let (server, mut ws_a, buf_a, mut ws_b, buf_b, path) =
        setup_overlapping_workspaces_watched_buffer("hello\n").await;
    assert_ne!(
        buf_a, buf_b,
        "each workspace should hold its own buffer for the path"
    );

    std::fs::write(&path, "hello world\n").unwrap();

    // Both buffers were clean, so both clients should see a silent reload.
    let push_a =
        expect_notification_within::<BufferState>(&mut ws_a, std::time::Duration::from_secs(5))
            .await;
    assert_eq!(push_a.buffer_id, buf_a);
    assert!(!push_a.externally_modified);
    let push_b =
        expect_notification_within::<BufferState>(&mut ws_b, std::time::Duration::from_secs(5))
            .await;
    assert_eq!(push_b.buffer_id, buf_b);
    assert!(!push_b.externally_modified);

    drop(server);
}

#[tokio::test]
async fn save_in_one_workspace_reloads_other_workspaces_buffer() {
    let (server, mut ws_a, buf_a, mut ws_b, buf_b, path) =
        setup_overlapping_workspaces_watched_buffer("hello\n").await;

    // Edit + save in workspace A. The self-save filter suppresses the event for A's buffer (its
    // recorded mtime matches the write) but must not suppress it for B's.
    let _: EditResult = send_request::<InputText>(
        &mut ws_a,
        &InputTextParams {
            buffer_id: buf_a,
            text: "from-a-".into(),
            select_pasted: false,
            replace_selection: false,
            at: None,
        },
    )
    .await;
    let _: BufferSaveResult = send_request::<BufferSave>(
        &mut ws_a,
        &BufferSaveParams {
            buffer_id: buf_a,
            path_index: None,
            relative_path: None,
            overwrite: false,
        },
    )
    .await;

    // B's buffer was clean → silent reload, announced via buffer/state.
    let push_b =
        expect_notification_within::<BufferState>(&mut ws_b, std::time::Duration::from_secs(5))
            .await;
    assert_eq!(push_b.buffer_id, buf_b);
    assert!(
        !push_b.externally_modified,
        "clean buffer should silently reload"
    );

    // Saving B without overwrite proves the reload landed: a stale-but-unflagged buffer would
    // clobber A's text on disk, and a flagged one would be rejected.
    let _: BufferSaveResult = send_request::<BufferSave>(
        &mut ws_b,
        &BufferSaveParams {
            buffer_id: buf_b,
            path_index: None,
            relative_path: None,
            overwrite: false,
        },
    )
    .await;
    assert_eq!(std::fs::read_to_string(&path).unwrap(), "from-a-hello\n");

    drop(server);
}

